/**
 * Typed decoders for every registry event (#134). Generated by
 * scripts/gen-events.py from contracts/interfaces/registry.rs; don't edit
 * by hand. `registryEvents.test.ts` fails when the contract gains an event
 * or field this file doesn't know.
 */
import type { RegistryEvent } from "./events.js";

/** How each field is encoded on-chain. */
export type FieldKind = "u64" | "i128" | "u32" | "bool" | "address" | "bytes" | "option_address";

/** Per event: its topic fields (after the name) and data fields, in order. */
export const EVENT_SPECS: Record<string, { topics: [string, FieldKind][]; data: [string, FieldKind][] }> = {
  admin_changed: { topics: [], data: [["previous", "address"], ["new_admin", "address"]] },
  admin_proposal_cancelled: { topics: [], data: [["current", "address"], ["cancelled", "address"]] },
  admin_proposed: { topics: [], data: [["current", "address"], ["proposed", "address"]] },
  executor_set: { topics: [], data: [["executor", "address"]] },
  job_active_set: { topics: [["job_id", "u64"]], data: [["active", "bool"]] },
  job_cancelled: { topics: [["job_id", "u64"]], data: [["refund", "i128"]] },
  job_created: { topics: [["job_id", "u64"]], data: [["owner", "address"], ["target", "address"], ["interval", "u64"], ["fee_per_run", "i128"], ["deposit", "i128"]] },
  job_deactivated: { topics: [["job_id", "u64"]], data: [["failures", "u32"]] },
  job_executed: { topics: [["job_id", "u64"], ["keeper", "address"]], data: [["success", "bool"], ["fee", "i128"], ["protocol_fee", "i128"], ["run", "u32"], ["next_run", "u64"], ["lateness", "u64"], ["failures", "u32"], ["result_hash", "bytes"]] },
  job_exhausted: { topics: [["job_id", "u64"]], data: [["balance", "i128"]] },
  job_funded: { topics: [["job_id", "u64"]], data: [["from", "address"], ["amount", "i128"], ["balance", "i128"]] },
  job_owner_changed: { topics: [["job_id", "u64"]], data: [["previous", "address"], ["new_owner", "address"]] },
  job_owner_proposed: { topics: [["job_id", "u64"]], data: [["owner", "address"], ["proposed", "address"]] },
  job_updated: { topics: [["job_id", "u64"]], data: [["interval", "u64"], ["fee_per_run", "i128"], ["max_runs", "u32"], ["end_at", "u64"]] },
  job_withdrawn: { topics: [["job_id", "u64"]], data: [["amount", "i128"], ["balance", "i128"]] },
  keeper_missed_window: { topics: [["keeper", "address"]], data: [["job_id", "u64"], ["ran_by", "address"]] },
  keeper_staked: { topics: [["keeper", "address"]], data: [["amount", "i128"], ["total", "i128"]] },
  keeper_unbonding: { topics: [["keeper", "address"]], data: [["withdrawable_at", "u64"]] },
  keeper_windows_set: { topics: [], data: [["grace_period", "u64"]] },
  keeper_withdrawn: { topics: [["keeper", "address"]], data: [["amount", "i128"]] },
  max_args_set: { topics: [], data: [["max_args", "u32"]] },
  max_failures_set: { topics: [], data: [["max_failures", "u32"]] },
  min_interval_set: { topics: [], data: [["min_interval", "u64"]] },
  min_stake_set: { topics: [], data: [["min_stake", "i128"]] },
  paused_set: { topics: [], data: [["paused", "bool"]] },
  protocol_fee_set: { topics: [], data: [["protocol_fee_bps", "u32"], ["treasury", "option_address"]] },
  target_halt_set: { topics: [["target", "address"]], data: [["halted", "bool"]] },
  unbonding_epoch_set: { topics: [], data: [["unbonding_epoch", "u64"]] },
  upgrade_cancelled: { topics: [], data: [["wasm_hash", "bytes"]] },
  upgrade_delay_set: { topics: [], data: [["upgrade_delay", "u64"]] },
  upgrade_proposed: { topics: [], data: [["wasm_hash", "bytes"], ["available_at", "u64"]] },
  upgraded: { topics: [], data: [["wasm_hash", "bytes"], ["previous_version", "u32"]] },
};

/** Fields every decoded event carries, from the RPC server. */
